import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3]

    names = ['Peter', 'Arnold', 'Eric']
    books = ['science fiction', 'mystery', 'romance']
    smoothies = ['watermelon', 'desert', 'cherry']
    birthdays = ['april', 'jan', 'sept']
    heights = ['average', 'very short', 'short']

    solutions = []

    for perm_names in permutations(names):
        # C7: Eric is in the first house.
        if perm_names[0] != 'Eric':
            continue

        idx_eric = perm_names.index('Eric')
        idx_arnold = perm_names.index('Arnold')

        for perm_books in permutations(books):
            # C2: Arnold loves mystery.
            if perm_books[idx_arnold] != 'mystery':
                continue

            # C4 will be checked when heights are assigned (romance <-> very short)

            for perm_smoothies in permutations(smoothies):
                # C1: Cherry not in house 2.
                if perm_smoothies[1] == 'cherry':
                    continue
                # C9: Watermelon smoothie lover is Eric.
                if perm_smoothies[idx_eric] != 'watermelon':
                    continue

                # C6 will be checked with heights (average <-> desert)
                # C8 will be checked with heights (watermelon <-> short)

                for perm_heights in permutations(heights):
                    # C8: Watermelon smoothie lover is short.
                    if perm_heights[perm_smoothies.index('watermelon')] != 'short':
                        continue
                    # C6: Average height <-> Desert smoothie.
                    if perm_heights[perm_smoothies.index('desert')] != 'average':
                        continue
                    # C4: Very short <-> Romance.
                    if perm_books[perm_heights.index('very short')] != 'romance':
                        continue

                    for perm_birthdays in permutations(birthdays):
                        # C3: January not in the first house.
                        if perm_birthdays[0] == 'jan':
                            continue
                        # C5: Mystery <-> September.
                        if perm_birthdays[perm_books.index('mystery')] != 'sept':
                            continue

                        # All constraints satisfied; record solution.
                        rows = []
                        for i in range(3):
                            rows.append([
                                str(i + 1),
                                perm_names[i],
                                perm_books[i],
                                perm_smoothies[i],
                                perm_birthdays[i],
                                perm_heights[i]
                            ])
                        solutions.append(rows)

    # Assuming a unique solution
    if not solutions:
        raise ValueError("No solution found.")
    solution_rows = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "BookGenre", "Smoothie", "Birthday", "Height"],
            "rows": solution_rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
